import Link from 'next/link';
import { ArrowRight, GraduationCap, PlayCircle, Sparkles } from 'lucide-react';
import { ClassLibrary, type ClassLibraryCard } from '@/components/course-portal/class-library';
import { CoursePortalShell } from '@/components/course-portal/portal-shell';
import { listClassLibrary } from '@/lib/server/class-library';

export const dynamic = 'force-dynamic';

export const metadata = {
  title: 'Class library | Linguistic Communication Academy',
  description:
    'Explore every class generated by Linguistic Communication Academy. No account and no access code required.',
};

export default async function ClassesPage() {
  const library = await listClassLibrary();

  const cards: ClassLibraryCard[] = library.entries.map((entry) => ({
    slug: entry.course.slug,
    title: entry.course.title,
    description: entry.course.description,
    category: entry.course.category || 'Linguistic Communication Academy',
    status: entry.course.status,
    level: entry.course.level,
    sceneCount: entry.sceneCount,
    durationMinutes: entry.course.estimatedDurationMinutes,
    coverTone: entry.course.coverTone,
    coverAsset: entry.course.coverAsset,
    playHref: entry.playHref,
    detailHref: `/classes/${entry.course.slug}`,
    organizationNames: entry.organizationNames,
    requiresCode: !entry.isOpen,
  }));

  return (
    <CoursePortalShell>
      <section className="mx-auto flex w-full max-w-7xl flex-col gap-6 px-4 py-10 sm:px-6 lg:px-8">
        <div className="flex items-center gap-2 text-sm font-semibold text-violet-700">
          <GraduationCap className="size-4" />
          Linguistic Communication Academy Class Library
        </div>
        <h1 className="max-w-4xl text-4xl font-semibold tracking-normal text-slate-950 md:text-5xl">
          Every class we have generated, open to explore
        </h1>
        <p className="max-w-3xl text-base leading-7 text-slate-600">
          Open any class below and play it like a learner would: slides, interactive exercises,
          quizzes and audio. No account, no access code, no setup.
        </p>
        <div className="flex flex-wrap gap-3">
          <span className="inline-flex items-center gap-2 rounded-md border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700">
            <Sparkles className="size-4 text-violet-700" />
            {library.entries.length} classes published
          </span>
          <span className="inline-flex items-center gap-2 rounded-md border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700">
            <PlayCircle className="size-4 text-violet-700" />
            {library.playableCount} playable right now
          </span>
          {library.entries.some((entry) => entry.organizationNames.length > 0) && (
            <Link
              href="/courses"
              className="inline-flex items-center gap-2 rounded-md border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:border-violet-200 hover:text-violet-800"
            >
              Institution catalogs
              <ArrowRight className="size-4" />
            </Link>
          )}
        </div>
      </section>
      <ClassLibrary cards={cards} categories={library.categories} />
    </CoursePortalShell>
  );
}
